G=load()

def transform(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    # find dash color: non-background
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    dash=[c for c in cnt if c!=bg]
    assert len(dash)==1
    d=dash[0]
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]==d]
        if len(cs)>=3:
            for c in range(min(cs),max(cs)+1):
                if g[r][c]==bg: g[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if g[r][c]==d]
        if len(rs)>=3:
            for r in range(min(rs),max(rs)+1):
                if g[r][c]==bg: g[r][c]=2
    return g

